# ---------------------------------------------------------------------------
# Shared parsing helpers.
#
# Every polarity verdict in this suite is adjudicated on an EXACT token, never
# on a substring: 'current polarity mdix' contains 'current polarity mdi', so a
# bare `in` test would let a port that resolved MDI-X satisfy a forced-MDI
# assertion (holistic review, TestCase_5/8/9/14).
# ---------------------------------------------------------------------------

CURRENT_POLARITY_RE = re.compile(r'current\s+polarity\s+(mdix|mdi|auto|none|n/a)\b', re.I)
CONFIGURED_POLARITY_RE = re.compile(r'configured\s+polarity\s+(mdix|mdi|auto|none|n/a)\b', re.I)
FIBRE_TYPE_RE = re.compile(
    r'\b('
    r'1000BASE-(?:SX|LX|LH|ZX|BX10?[DU]?|EX|EZX)'
    r'|100BASE-(?:FX|BX10?[DU]?|LX)'
    r'|10GBASE-(?:SR|LR|ER|ZR|LRM|BX[DU]?)'
    r'|25GBASE-(?:SR|LR|ER)'
    r'|40GBASE-(?:SR4|LR4|ER4)'
    r'|100GBASE-(?:SR4|LR4|ER4|CWDM4|PSM4)'
    r')\b', re.I)
COPPER_TYPE_RE = re.compile(r'\b(?:10|100|1000|2\.5G|5G|10G)BASE-T\b', re.I)

# The CLI parser markers this platform emits when it refuses a command. Used
# instead of a bare 'error'/'invalid' substring scan of the echoed command,
# which matches the word 'mdi-x' style arguments and the echo itself.
PARSER_ERROR_MARKERS = (
    '% Invalid input detected',
    'Invalid input detected',
    '% Incomplete command',
    'Incomplete command',
    '% Unrecognized command',
    'Unrecognized command',
    '% Ambiguous command',
    'Ambiguous command',
    '% Unknown command',
    'Unknown command',
)

# Markers meaning "the parser understood it but the media/port refuses it".
# DELIBERATE: 'copper' is a bare media noun and it belongs here. This is a COPPER-ONLY
# feature test — fibre has no MDI/MDI-X concept at all (TOPOLOGY-PROFILES.md) — so a
# device replying to `polarity mdi` on a FIBRE port with any message that names copper is
# refusing on media grounds, which is exactly what step 19 sets out to observe. The real
# refusal wording is not captured anywhere, so narrowing this to guessed phrases would
# make a correctly-behaving device FAIL. Do not "tighten" it without device output.
NOT_APPLICABLE_MARKERS = (
    'not supported',
    'not applicable',
    'cannot be applied',
    'is not valid on',
    'only applicable to',
    'copper',
)


def cli_rejected(response):
    """True when the CLI parser refused the command outright."""
    if response is None:
        return False
    return any(marker in response for marker in PARSER_ERROR_MARKERS)


def cli_refused_for_media(response):
    """True when the device says the setting does not apply to this media."""
    if response is None:
        return False
    if cli_rejected(response):
        return True
    low = response.lower()
    return any(marker in low for marker in NOT_APPLICABLE_MARKERS)


def force_partner_polarity(testCase, peer, portDut, value):
    """Apply 'polarity <value>' on the PARTNER port and adjudicate CLI acceptance.

    Steps 7 and 10 make the partner take a fixed role so the mismatched pairing can be
    observed going DOWN - a test that cannot go negative while the partner stays on auto.
    Returns the response text, or None after recording failed() when the parser rejected it.
    """
    peer.mode(')#')
    peer.cmd('interface {}'.format(portDut.name))
    response = peer.cmd('polarity {}'.format(value))
    peer.mode('#')
    testCase.log("OBSERVED: partner {} 'polarity {}' response: {}".format(portDut.name, value, response))
    if cli_rejected(response):
        testCase.failed("partner {} rejected 'polarity {}': {}".format(portDut.name, value, response.strip()))
        return None
    testCase.passed("partner {} accepted 'polarity {}' with no CLI parser error".format(portDut.name, value))
    return response


def assert_role_media_now(testCase, dut, port, role):
    """Deferred half of `TestSet._ck_bind_link`: assert the media of a PLUGGABLE role AFTER the
    operator-insertion case has confirmed the module is fitted.

    Module-level on purpose: the frame's lint reads every `self.testSet.<name>` as a device
    handle that init() must bind. Returns True/False and records the verdict on `testCase`,
    because by this point a wrong module IS a test-relevant observation the operator can
    correct - unlike at init time, where it is a bench-configuration error that must abort.
    """
    import ck_media
    status = dut.cmd('show interface %s status' % port.name)
    ok, why = ck_media.assert_role_media(status, port.name, role)
    if ok:
        testCase.passed('inserted module on %s matches the %r role: %s' % (port.name, role, why))
    else:
        testCase.failed('inserted module on %s does NOT match the %r role: %s' % (port.name, role, why))
    return ok


def current_polarity(output):
    """Return the exact resolved polarity token, or None when not presented."""
    match = CURRENT_POLARITY_RE.search(output or '')
    if not match:
        return None
    return match.group(1).lower()


def configured_polarity(output):
    """Return the exact configured polarity token, or None when not presented."""
    match = CONFIGURED_POLARITY_RE.search(output or '')
    if not match:
        return None
    return match.group(1).lower()


def complement_of(polarity):
    return {'mdi': 'mdix', 'mdix': 'mdi'}.get(polarity)


def status_row(output, port_name):
    """The single `show interface <port> status` row that belongs to port_name."""
    for line in (output or '').splitlines():
        tokens = line.split()
        if tokens[:1] == [port_name]:
            return line
    return None


def link_state_token(output, port_name):
    """'connected' / 'notconnect' / 'disabled' ... from a scoped status row."""
    row = status_row(output, port_name)
    if row is None:
        return None, None
    for token in row.split():
        low = token.lower()
        if low in ('connected', 'notconnect', 'disabled', 'err-disabled',
                   'monitoring', 'faulty', 'inactive'):
            return low, row
    return None, row


class TestSet(ATTestSet.TestSet):

    FEATURES = ['ALL']

    def _ck_discover(self, dut, unit=None):
        """Every data link on the DUT, classified by asking the DUT what is fitted in each port.

        `dut` is the switch handle commands go to; `unit` is what owns the ports — the STACK
        when the DUT is in one (its members' [portlink]s all count), else `dut` itself.

        Fixed frame — do not edit or delete (manual port of the 2026-09-21 discovery frame to
        this saved script, 2026-09-23). Nothing is pre-declared: the cables come from the
        bench's own [portlink] section through `get_all_port_links()`; the testbox is the far
        end that is a TestBox; a member of the DUT's own stack is never a partner; and the
        MEDIA of each DUT-side port is read from `show interface <port> status` (its Type
        column) and `show system pluggable` (which cages hold a module). A LAG member is an
        ordinary partner link (Terrence, 2026-09-23). An EMPTY cage lands in `absent`, and no
        role takes it: it has no media (the frame's rule).
        Returns {bucket: [(near_port, far_port, far_device), ...]} for the buckets
        tb / copper (fixed twisted pair) / cusfp (twisted pair in a cage) / fibre / absent / unknown.
        """
        import ck_media
        unit = unit if unit is not None else dut
        members = set(unit.all_members()) if hasattr(unit, 'all_members') else set()
        in_cage = ck_media.pluggable_ports(dut.cmd('show system pluggable'))
        found = {'tb': [], 'copper': [], 'cusfp': [], 'fibre': [], 'absent': [], 'unknown': []}
        for far, pairs in unit.get_all_port_links().items():
            if far in members:
                continue                       # stackport / member cabling is not a data path
            for near, far_port in pairs:
                if isinstance(far, ATTestBox.TestBox):
                    found['tb'].append((near, far_port, far))
                    continue
                if not near.name.startswith('port'):
                    continue                   # an eth0 management link is not a data path
                status = dut.cmd('show interface %s status' % near.name)
                kind = ck_media.classify(ck_media.media_type(status, near.name))
                if kind == ck_media.TWISTED_PAIR:
                    bucket = 'cusfp' if ck_media.is_pluggable(near.name, in_cage) else 'copper'
                elif kind == ck_media.FIBRE:
                    bucket = 'fibre'
                elif kind == ck_media.ABSENT:
                    bucket = 'absent'
                else:
                    bucket = 'unknown'
                found[bucket].append((near, far_port, far))
        self.log('topology discovered on %s: %s' % (dut.name, '; '.join(
            '%s=%s' % (k, ','.join('%s<->%s.%s' % (n.name, getattr(f, 'name', 'tb'), p.name)
                                    for n, p, f in v))
            for k, v in found.items() if v) or 'NO data links declared'))
        return found

    def _ck_bind_link(self, setup, dut, role, optional=False):
        """Take ONE discovered link for `role` and bind it: (near_port, far_port, far_device).

        `role` is what the TEST needs — 'tb', 'copper', 'fibre', 'cusfp'. A link is never
        handed out twice; a copper role takes a copper SFP only when no fixed twisted-pair link
        is left; a partner switch is initialised once however many links go to it. A REQUIRED
        role with no link aborts the suite ("this bench cannot host this test" is a bench
        problem, not a test result); an OPTIONAL role returns (None, None, None).

        PLUGGABLE roles (cusfp, fibre) take only a FITTED module of their media, as the frame
        does (Terrence, 2026-09-23: "we should follow the frame, whenever possible"). An empty
        cage is no role. Fitting the modules before the run is this script's PRECONDITION (see
        the header).
        """
        import ck_media
        buckets = {'tb': ('tb',), 'copper': ('copper', 'cusfp'),
                   'cusfp': ('cusfp',), 'fibre': ('fibre',)}[role]
        for bucket in buckets:
            if not self._ck_topo.get(bucket):
                continue
            near, far_port, far = self._ck_topo[bucket].pop(0)
            if not isinstance(far, ATTestBox.TestBox):
                if far.name not in self._ck_far:
                    self._ck_far[far.name] = (setup.init_stk(far.name) if hasattr(far, 'all_members')
                                              else setup.init_swi(far.name))
                far = self._ck_far[far.name]
            self.log('topology: role %r -> %s %s <-> %s %s (%s)' % (
                role, dut.name, near.name, getattr(far, 'name', 'tb'), far_port.name, bucket))
            return near, far_port, far
        have = ', '.join('%d %s' % (len(v), k) for k, v in self._ck_topo.items() if v) or 'none'
        why = ("BENCH PROBLEM, not a product defect: no unused %s link on %s (data links "
               "discovered: %s). Cable a %s partner port to the DUT and declare it under "
               "[portlink]." % (role, dut.name, have, role))
        if optional:
            self.log(why + ' This role is OPTIONAL here: the cases needing it report UNSUPPORTED.')
            return None, None, None
        raise RuntimeError(why)

    def init(self, setup):
        # Topology is DISCOVERED through the framework at run time, never declared to this
        # script (manual port of the 2026-09-21 frame, 2026-09-23; the [misc] role contract
        # this script used to read is retired): the DUT is the framework's `swi_a` slot (its
        # stack, when it is in one), the partners are whatever the bench's [portlink]s cable to
        # it, and which link is copper / fibre / copper-SFP is read from the DUT itself.
        tb = setup.init_tb()
        dut = setup.init_swi('swi_a')
        # ART's own shape: the STACK owns the ports [portlink] declares per member and is what
        # discovery walks; COMMANDS go to the swi_a member handle, which has cmd()/mode() — the
        # framework's Stack class defines neither, and every VCStack member serves the
        # stack-wide CLI (Terrence, 2026-09-23: "Copy what they do, because it works.").
        _stk = dut.get_stack()
        dut_stack = setup.init_stk(_stk.name) if _stk is not None else None
        self.tb = tb
        self.dut = dut
        self.dut_stack = dut_stack
        self._ck_far = {}
        self._ck_topo = self._ck_discover(dut, dut_stack)

        # ---------------------------------------------------------------
        # ROLE SET for this case (holistic review, TestSet.init):
        #
        #   copper    DUT copper RJ45 test port  <-> PARTNER SWITCH copper port. The link
        #             every copper step measures at BOTH ends. REQUIRED.
        #   cusfp     DUT cage for the COPPER SFP module <-> partner port (steps 16-17).
        #   fibre     DUT cage for the FIBRE SFP module <-> partner port (steps 18-19).
        #   tb        testbox data link — not needed by this case (CLI at both ends).
        #
        # The pluggable roles are bound FIRST so the copper role cannot consume a copper-SFP
        # link, and `cusfp` / `fibre` are DISTINCT handles so the copper-SFP and fibre-SFP
        # assertions are never aimed at one port attribute (holistic review, TestCase_16/17).
        # ---------------------------------------------------------------
        (dut.portCuSfp, cusfp_far_port, cusfp_peer) = self._ck_bind_link(
            setup, dut, 'cusfp', optional=True)
        self.cusfp_supported = cusfp_peer is not None
        if self.cusfp_supported:
            cusfp_peer.portCuSfp = cusfp_far_port
        else:
            self.cusfp_reason = ('no copper SFP fitted in a partner-cabled cage at init() — fit one before the run '
                                 '(PRECONDITION)')
        self.cusfp_peer = cusfp_peer
        self.cusfp_far_port = cusfp_far_port

        (dut.portFibre, fibre_far_port, fibre_peer) = self._ck_bind_link(
            setup, dut, 'fibre', optional=True)
        self.fibre_supported = fibre_peer is not None
        if self.fibre_supported:
            fibre_peer.portFibre = fibre_far_port
        else:
            self.fibre_reason = ('no fibre SFP fitted in a partner-cabled cage at init() — fit one before the run '
                                 '(PRECONDITION)')
        self.fibre_peer = fibre_peer
        self.peer_fibre_port = fibre_far_port
        # Backwards-compatible alias: `portPeer` has always meant "the DUT's fibre SFP port" in
        # steps 18/19; keep the name pointing at exactly that.
        dut.portPeer = dut.portFibre

        (dut.portA, partner_copper_port, partner) = self._ck_bind_link(setup, dut, 'copper')
        partner.portDut = partner_copper_port
        self.peer = partner

        # The TESTBOX data link: optional here — this case drives everything from the CLI at
        # both ends of a switch-to-switch cable.
        (dut.portTb, tb.ethA, _tb) = self._ck_bind_link(setup, dut, 'tb', optional=True)

        # Baselines recorded by one case and adjudicated by another.
        self.mdi_polarity_dut_straight = None
        self.mdi_polarity_peer_straight = None

    def configure(self):
        tb = self.tb
        dut = self.dut
        ethA = getattr(tb, 'ethA', None)
        portA = dut.portA
        peer = self.peer
        portFibre = dut.portFibre
        portDut = peer.portDut
        # One-time SUITE setup, runs ONCE before all test cases. Config only — no pass/fail.
        # setup: On the DUT and the link partner, enter configuration mode and set the copper
        # test port and the partner port to auto-negotiation and full duplex defaults:
        # 'interface <port>', 'duplex auto' on each, and ensure neither port has an explicit
        # polarity command applied. Ensure both ports are administratively enabled.
        # Step 1's CLI responses are STASHED for TestCase_1 (step 2) to adjudicate: this
        # method is config-only and may hold no verdict.
        self.step1_responses = []
        dut.mode(')#')
        for cmd in ('interface {}'.format(portA.name), 'duplex auto', 'no polarity', 'no shutdown'):
            self.step1_responses.append(('DUT', cmd, dut.cmd(cmd)))
        dut.mode('#')

        peer.mode(')#')
        for cmd in ('interface {}'.format(portDut.name), 'duplex auto', 'no polarity', 'no shutdown'):
            self.step1_responses.append(('partner', cmd, peer.cmd(cmd)))
        peer.mode('#')

        # Fibre neighbour link: enabled, no polarity forced. OPTIONAL role - init() leaves
        # dut.portFibre / self.fibre_peer as None on a bench without it; steps 1-15 still run.
        fibre_peer = self.fibre_peer
        if self.fibre_supported and portFibre is not None and fibre_peer is not None:
            dut.mode(')#')
            dut.cmd('interface {}'.format(portFibre.name))
            dut.cmd('no shutdown')
            dut.mode('#')
            fibre_peer.mode(')#')
            fibre_peer.cmd('interface {}'.format(fibre_peer.portFibre.name))
            fibre_peer.cmd('no shutdown')
            fibre_peer.mode('#')

    def tear_down(self):
        tb = self.tb
        dut = self.dut
        portA = dut.portA
        peer = self.peer
        portFibre = dut.portFibre
        portDut = peer.portDut
        # One-time SUITE cleanup, runs ONCE after all cases. No pass/fail.
        dut.mode(')#')
        dut.cmd('interface {}'.format(portA.name))
        dut.cmd('no polarity')
        dut.cmd('duplex auto')
        dut.cmd('no shutdown')
        dut.mode('#')

        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('no polarity')
        peer.cmd('duplex auto')
        peer.cmd('no shutdown')
        peer.mode('#')

        # OPTIONAL fibre role: None on a bench that does not declare it.
        if self.fibre_supported and portFibre is not None:
            dut.mode(')#')
            dut.cmd('interface {}'.format(portFibre.name))
            dut.cmd('no shutdown')
            dut.mode('#')


class TestCase_1(ATTestCase.TestCase):
    testCaseDesc = "With the straight-through copper cable connecting the DUT test port to the partner port, read 'show interface <port>' on the DUT and 'show interface <partner port>' on the partner, and read 'show interface <port> status' on both."
    testCaseRef = 'AWPTCM-T33234, 9001.33234.1'
    testCaseMethod = "With the straight-through copper cable connecting the DUT test port to the partner port, read 'show interface <port>' on the DUT and 'show interface <partner port>' on the partner, and read 'show interface <port> status' on both.\n"
    testCaseMethod += "Verify: 'show interface <port>' reports the link as up on both ends and prints a current polarity of either mdi or mdix on each; 'show interface <port> status' shows the port 'connected' with an auto-negotiated duplex/speed (e.g. 'a-full'). Record the resolved polarity value at each end. For a straight-through cable the two ends must report opposite roles (one mdi, one mdix).\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        # Establish the precondition this step presumes: both ends of the
        # straight-through copper link are left at default (auto) speed,
        # duplex and polarity so the resolved polarity/duplex/speed observed
        # in main() reflects genuine auto-negotiation, not a leftover forced
        # setting from another case.
        #
        # NOTE (holistic review): this is the COPPER test port portA and the
        # partner switch port at the other end of the same cable — not the
        # fibre role port.
        configureDefaultPort(self, dut, portA)
        configureDefaultPort(self, peer, portDut)
        time.sleep(3)

    def main(self):
        # legacy 5000_mdi_mdix/library_5000.py lines 207-238
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        self.log("STEP 2: With the straight-through copper cable connecting the DUT test port to the partner port, read 'show interface <port>' on the DUT and 'show interface <partner port>' on the partner, and read 'show interface <port> status' on both.")

        # STEP 1 is performed in TestSet.configure (config-only, no verdicts); its verify is
        # adjudicated here from the responses configure() stashed.
        step1_responses = getattr(self.testSet, 'step1_responses', None)
        if not step1_responses:
            self.failed('STEP 1: TestSet.configure recorded no responses to the defaulting commands, '
                        'so they cannot be checked for CLI parser errors')
            return
        rejected = [(who, cmd, (resp or '').strip()) for who, cmd, resp in step1_responses
                    if cli_rejected(resp)]
        if rejected:
            self.failed('STEP 1: defaulting command(s) rejected by the CLI parser: {}'.format(rejected))
            return
        self.passed('STEP 1: all {} defaulting commands on DUT and partner accepted with no CLI parser '
                    'error'.format(len(step1_responses)))
        dut.mode('#')
        dut_running = dut.cmd('show running-config interface {}'.format(portA.name))
        peer.mode('#')
        peer_running = peer.cmd('show running-config interface {}'.format(portDut.name))
        self.log('OBSERVED: DUT running-config {}:\n{}\npartner running-config {}:\n{}'.format(
            portA.name, dut_running, portDut.name, peer_running))
        dut_forced = re.search(r'^\s*polarity\s+(mdi|mdix)\s*$', dut_running, re.M)
        peer_forced = re.search(r'^\s*polarity\s+(mdi|mdix)\s*$', peer_running, re.M)
        if dut_forced or peer_forced:
            self.failed('STEP 1: an explicit polarity line remains in running-config (DUT: {!r}, '
                        'partner: {!r}); the default automatic setting is not in place'.format(
                            dut_forced.group(0).strip() if dut_forced else None,
                            peer_forced.group(0).strip() if peer_forced else None))
            return
        self.passed('STEP 1: no explicit polarity line in running-config on DUT {} or partner {} - the '
                    'default automatic setting is in place'.format(portA.name, portDut.name))

        # Let auto-negotiation settle after configure() put both ends back to auto.
        deadline = time.time() + 60
        dut.mode('#')
        while time.time() < deadline:
            state, _row = link_state_token(
                dut.cmd('show interface {} status'.format(portA.name), log=False), portA.name)
            if state == 'connected':
                break
            time.sleep(2)

        dut.mode('#')
        dut_output = dut.cmd('show interface {}'.format(portA.name))
        peer.mode('#')
        peer_output = peer.cmd('show interface {}'.format(portDut.name))
        dut.mode('#')
        dut_status = dut.cmd('show interface {} status'.format(portA.name))
        peer.mode('#')
        peer_status = peer.cmd('show interface {} status'.format(portDut.name))

        output = (
            'DUT show interface {}:\n{}\n'
            'Peer show interface {}:\n{}\n'
            'DUT show interface status:\n{}\n'
            'Peer show interface status:\n{}'
        ).format(portA.name, dut_output, portDut.name, peer_output, dut_status, peer_status)
        self.log('OBSERVED: {}'.format(output))

        dut_up = 'Link is UP' in dut_output
        peer_up = 'Link is UP' in peer_output

        if not (dut_up and peer_up):
            self.failed('Link not reported UP on both ends: DUT {} up={}, peer {} up={}'.format(
                portA.name, dut_up, portDut.name, peer_up))
            return
        self.passed('Link reported UP on both DUT port {} and peer port {}'.format(
            portA.name, portDut.name))

        # Exact-token parse: 'current polarity mdix' must never satisfy an 'mdi' test.
        dut_polarity = current_polarity(dut_output)
        peer_polarity = current_polarity(peer_output)

        if dut_polarity not in ('mdi', 'mdix'):
            self.failed('DUT port {} did not report a current polarity of mdi or mdix: {}'.format(
                portA.name, dut_polarity))
            return
        if peer_polarity not in ('mdi', 'mdix'):
            self.failed('Peer port {} did not report a current polarity of mdi or mdix: {}'.format(
                portDut.name, peer_polarity))
            return
        self.passed('Resolved polarity recorded: DUT port {} = {}, peer port {} = {}'.format(
            portA.name, dut_polarity, portDut.name, peer_polarity))

        # Publish the straight-through baseline so step 5 can adjudicate the
        # mandatory "inverse assignment" clause of its verify instead of
        # skipping it (holistic review, TestCase_4).
        self.testSet.mdi_polarity_dut_straight = dut_polarity
        self.testSet.mdi_polarity_peer_straight = peer_polarity
        self.log('RECORDED straight-through baseline: DUT={}, peer={}'.format(
            dut_polarity, peer_polarity))

        if dut_polarity != peer_polarity:
            self.passed('Straight-through cable resolved opposite MDI/MDI-X roles: DUT={}, peer={}'.format(
                dut_polarity, peer_polarity))
        else:
            self.failed('Expected opposite polarity roles for a straight-through cable, both ends reported {}'.format(
                dut_polarity))
            return

        dut_row = status_row(dut_status, portA.name)
        peer_row = status_row(peer_status, portDut.name)

        if dut_row is None or peer_row is None:
            self.failed('Port missing from show interface status output: DUT row={}, peer row={}'.format(
                dut_row, peer_row))
            return

        dut_tokens = dut_row.split()
        peer_tokens = peer_row.split()
        dut_connected = 'connected' in dut_tokens
        peer_connected = 'connected' in peer_tokens
        dut_auto_neg = any(token.startswith('a-') for token in dut_tokens)
        peer_auto_neg = any(token.startswith('a-') for token in peer_tokens)

        if dut_connected and peer_connected and dut_auto_neg and peer_auto_neg:
            self.passed(
                'show interface status reports connected with auto-negotiated duplex/speed on both '
                'ends: DUT row="{}", peer row="{}"'.format(dut_row, peer_row))
        else:
            self.failed(
                'show interface status did not report connected/auto-negotiated on both ends: '
                'DUT row="{}", peer row="{}"'.format(dut_row, peer_row))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        # main() only reads state; configure() already left both ends at the
        # default (auto) speed/duplex/polarity, so there is nothing further
        # to revert here.
        pass


class TestCase_2(ATTestCase.TestCase):
    testCaseDesc = "On the DUT copper test port that has never been explicitly configured for polarity, read 'show running-config interface <port>' and 'show interface <port>'."
    testCaseRef = 'AWPTCM-T33234, 9001.33234.2'
    testCaseMethod = "On the DUT copper test port that has never been explicitly configured for polarity, read 'show running-config interface <port>' and 'show interface <port>'.\n"
    testCaseMethod += "Verify: 'show running-config interface <port>' contains no 'polarity' line, proving auto is the default; 'show interface <port>' reports a resolved current polarity of mdi or mdix (the operational role), not merely the configured mode.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        # Establish the precondition this step presumes: the test port at its
        # factory-default speed/duplex/polarity, i.e. never explicitly overridden.
        configureDefaultPort(self, dut, portA)
        configureDefaultPort(self, peer, portDut)
        time.sleep(3)

    def main(self):
        # legacy 5000_mdi_mdix/test-5000.0001-CopperFixed_Straight.py lines 2007-2081
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        self.log("STEP 3: On the DUT copper test port that has never been explicitly configured for polarity, "
                 "read 'show running-config interface <port>' and 'show interface <port>'.")

        if waitForLinkState(self, dut, portA, 'connected', 60):
            self.passed('{} link is up, so a resolved current polarity can be observed'.format(portA.name))
        else:
            self.failed('{} link is not connected; no current polarity can be observed'.format(portA.name))
            return

        dut.mode('#')
        running_output = dut.cmd('show running-config interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(running_output))
        # Anchored: a FORCED override is a 'polarity mdi|mdix' line of its own; an explicit
        # 'polarity auto' line is still the default (step 13's verify says so), and a bare
        # substring test would trip on any unrelated line containing the word.
        forced_line = re.search(r'^\s*polarity\s+(mdi|mdix)\s*$', running_output, re.M)
        if forced_line is None:
            self.passed(
                "show running-config interface {} contains no forced 'polarity mdi|mdix' line, proving auto "
                "is the default".format(portA.name))
        else:
            self.failed(
                "show running-config interface {} unexpectedly contains a forced polarity line {!r}: {}".format(
                    portA.name, forced_line.group(0).strip(), running_output))
            return

        if checkConfiguredPort(self, dut, portA, 'auto', 'auto', 'auto'):
            self.passed(
                '{} configured duplex/speed/polarity all read auto, confirming no explicit override'.format(
                    portA.name))
        else:
            self.failed(
                '{} configured duplex/speed/polarity do not all read auto, an override may be present'.format(
                    portA.name))
            return

        interface_output = dut.cmd('show interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(interface_output))
        resolved = current_polarity(interface_output)

        if resolved in ('mdi', 'mdix'):
            self.passed('{} resolved current polarity is {}'.format(portA.name, resolved))
        else:
            self.failed(
                '{} did not report a resolved current polarity of mdi or mdix: {}'.format(
                    portA.name, interface_output))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        # Mirror configure(): clear any explicit speed/duplex/polarity so the port is
        # left with nothing configured, ready for the next case.
        dut.mode(')#')
        dut.cmd('interface {}'.format(portA.name))
        dut.cmd('no speed')
        dut.cmd('no duplex')
        dut.cmd('no polarity')
        dut.mode('#')


class TestCase_3(ATTestCase.TestCase):
    testCaseDesc = "Prompt the operator to unplug the straight-through copper cable between the DUT test port and the partner port and replace it with a crossover cable, leaving both ends on automatic polarity; then poll 'show interface <port> status' on the DUT until the port transitions down and back to 'connected'."
    testCaseRef = 'AWPTCM-T33234, 9001.33234.3'
    testCaseMethod = "Prompt the operator to unplug the straight-through copper cable between the DUT test port and the partner port and replace it with a crossover cable, leaving both ends on automatic polarity; then poll 'show interface <port> status' on the DUT until the port transitions down and back to 'connected'.\n"
    testCaseMethod += "Verify: Operator confirms the cable swap; the DUT test port is observed going down and then returning to 'connected' in 'show interface <port> status' within the link-up timeout.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        # Precondition this step presumes: both ends of the copper link are at their
        # default (automatic) speed/duplex/polarity settings before the cable is swapped,
        # matching the action's "leaving both ends on automatic polarity".
        configureDefaultPort(self, dut, portA)
        configureDefaultPort(self, peer, portDut)

    def main(self):
        # SVT 3009_pluggable_qualifications/libPluggableAutomateConfig.py lines 149-193
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        self.log("STEP 4: Prompt the operator to unplug the straight-through copper cable between the DUT test port and the partner port and replace it with a crossover cable, leaving both ends on automatic polarity; then poll 'show interface <port> status' on the DUT until the port transitions down and back to 'connected'.")
        port = portA

        # PRECONDITION (logged, not adjudicated): this step exists to demonstrate the
        # down/up transition across the cable swap, not to re-verify configuration that
        # TestCase_2 already asserts. Record the auto state for diagnosis only
        # (holistic review, TestCase_3).
        pre_dut_auto = checkConfiguredPort(self, dut, portA, 'auto', 'auto', 'auto')
        pre_peer_auto = checkConfiguredPort(self, peer, portDut, 'auto', 'auto', 'auto')
        self.log('PRECONDITION (informational): configured auto/auto/auto — DUT {}={}, '
                 'peer {}={}'.format(portA.name, pre_dut_auto, portDut.name, pre_peer_auto))

        # The down-then-up transition can only be OBSERVED if the link is up to begin with.
        if not waitForLinkState(self, dut, portA, 'connected', 60):
            self.failed('DUT port {} is not connected with the straight-through cable before the swap; '
                        'the down-then-up transition cannot be observed'.format(port.name))
            return
        self.passed('DUT port {} is connected with the straight-through cable before the swap'.format(
            port.name))

        self.log("OPERATOR: unplug the straight-through cable between {} and {}, replace it with a "
                 "crossover cable, leave both ends on automatic polarity.".format(port.name, portDut.name))

        # The verify names an operator confirmation: ask for it explicitly, the same way
        # TestCase_7 does, so the physical action is acknowledged and not merely assumed.
        swap_started = yesNo(
            'Unplug the STRAIGHT-THROUGH cable between DUT port {} and partner port {} now. '
            'Confirm when the cable has been REMOVED'.format(port.name, portDut.name))
        if not swap_started:
            self.failed('Operator did not confirm removal of the straight-through cable between '
                        '{} and {}'.format(port.name, portDut.name))
            return
        self.passed('Operator confirmed removal of the straight-through cable between {} and {}'.format(
            port.name, portDut.name))

        # Phase 1: the port must be observed leaving 'connected' once the operator removes
        # the straight-through cable.
        down_deadline = time.time() + 60
        state = None
        row = ''
        down_seen = False
        dut.mode('#')
        while time.time() < down_deadline:
            output = dut.cmd('show interface {} status'.format(port.name), log=False)
            state, row = link_state_token(output, port.name)
            # Row-scoped ABSENCE of the up state, so an unlisted down-state spelling still counts.
            if row is not None and state != 'connected':
                down_seen = True
                break
            self.log('Waiting for operator to remove the straight-through cable on {}'.format(port.name))
            time.sleep(2)
        self.log('OBSERVED (down phase): row={}'.format(row))
        if down_seen:
            self.passed('DUT port {} left the connected state after the cable was removed: {}'.format(
                port.name, row))
        else:
            self.failed('DUT port {} never left the connected state within timeout while awaiting cable '
                        'removal: {}'.format(port.name, row))
            return

        swap_done = yesNo(
            'Now insert the CROSSOVER cable between DUT port {} and partner port {}, leaving both '
            'ends on automatic polarity. Confirm when the crossover cable is FITTED'.format(
                port.name, portDut.name))
        if not swap_done:
            self.failed('Operator did not confirm insertion of the crossover cable between {} and '
                        '{}'.format(port.name, portDut.name))
            return
        self.passed('Operator confirmed the straight-through to crossover cable swap between {} and '
                    '{}'.format(port.name, portDut.name))

        # Phase 2: with the crossover cable inserted, the port must return to 'connected'
        # within the link-up timeout.
        up_deadline = time.time() + 120
        up_seen = False
        row = ''
        while time.time() < up_deadline:
            output = dut.cmd('show interface {} status'.format(port.name), log=False)
            state, row = link_state_token(output, port.name)
            if state == 'connected':
                up_seen = True
                break
            self.log('Waiting for operator to insert the crossover cable on {}'.format(port.name))
            time.sleep(2)
        self.log('OBSERVED (up phase): row={}'.format(row))
        if up_seen:
            self.passed("DUT port {} returned to 'connected' with the crossover cable within the "
                        "link-up timeout: {}".format(port.name, row))
        else:
            self.failed("DUT port {} did not return to 'connected' with the crossover cable within the "
                        "link-up timeout: {}".format(port.name, row))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        # configure() left both ends at their default (auto) settings, which is also the
        # desired steady state after this step; nothing further to revert.
        pass


class TestCase_4(ATTestCase.TestCase):
    testCaseDesc = "With the crossover cable in place and both ends still on automatic polarity, read 'show interface <port>' on the DUT and on the partner."
    testCaseRef = 'AWPTCM-T33234, 9001.33234.4'
    testCaseMethod = "With the crossover cable in place and both ends still on automatic polarity, read 'show interface <port>' on the DUT and on the partner.\n"
    testCaseMethod += 'Verify: Link is up at both ends; each end reports a current polarity of mdi or mdix. With a crossover cable the two ends must resolve to the SAME role (both mdi or both mdix) - the cable supplies the crossover - and compared with the roles recorded with the straight-through cable in step 2, exactly ONE end has inverted its role.\n'

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        # Precondition this step presumes: both ends still on automatic speed, duplex
        # and polarity. Established here (not inherited from another TestCase) so this
        # unit is self-contained; the crossover cable itself is a bench-level physical
        # precondition outside script control.
        configureDefaultPort(self, dut, portA)
        configureDefaultPort(self, peer, portDut)
        time.sleep(3)

    def main(self):
        # legacy 5000_mdi_mdix/library_5000.py lines 207-238
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        self.log("STEP 5: With the crossover cable in place and both ends still on automatic polarity, read 'show interface <port>' on the DUT and on the partner.")

        dut_link_ok = waitForLinkState(self, dut, portA, 'connected', 60)
        peer_link_ok = waitForLinkState(self, peer, portDut, 'connected', 60)

        dut.mode('#')
        dut_output = dut.cmd('show interface {}'.format(portA.name))
        peer.mode('#')
        peer_output = peer.cmd('show interface {}'.format(portDut.name))
        output = 'DUT {}:\n{}\nPEER {}:\n{}'.format(portA.name, dut_output, portDut.name, peer_output)
        self.log('OBSERVED: {}'.format(output))

        if not dut_link_ok or not peer_link_ok:
            self.failed('Link is not up at both ends with the crossover cable in place (DUT up={}, '
                        'peer up={})'.format(dut_link_ok, peer_link_ok))
            return
        self.passed('Link is up at both ends with the crossover cable in place')

        dut_polarity = current_polarity(dut_output)
        peer_polarity = current_polarity(peer_output)

        if dut_polarity in ('mdi', 'mdix') and peer_polarity in ('mdi', 'mdix'):
            self.passed('DUT port {} reports current polarity {}, peer port {} reports current polarity '
                        '{}'.format(portA.name, dut_polarity, portDut.name, peer_polarity))
        else:
            self.failed('DUT port {} current polarity {}, peer port {} current polarity {}; expected mdi '
                        'or mdix at each end'.format(portA.name, dut_polarity, portDut.name, peer_polarity))
            return

        # A CROSSOVER cable supplies the crossover itself, so a working link needs the SAME
        # role at both ends (both mdi or both mdix) - the opposite of the straight-through case.
        if dut_polarity == peer_polarity:
            self.passed('DUT and peer resolved the SAME role over the crossover cable ({} / {}) - the pairing '
                        'that links through a crossover'.format(dut_polarity, peer_polarity))
        else:
            self.failed('DUT {} / peer {} resolved opposite roles over the crossover cable; a crossover link '
                        'needs the same role at both ends'.format(dut_polarity, peer_polarity))
            return

        # The inverse-of-step-2 comparison is MANDATORY in this step's verify, so a
        # missing baseline is a failure of this case, not an INFO log
        # (holistic review, TestCase_4). TestCase_1 publishes the baseline.
        straight_dut_polarity = getattr(self.testSet, 'mdi_polarity_dut_straight', None)
        straight_peer_polarity = getattr(self.testSet, 'mdi_polarity_peer_straight', None)

        if not straight_dut_polarity or not straight_peer_polarity:
            self.failed(
                'The straight-through polarity baseline from step 2 was not recorded (DUT={}, peer={}), '
                'so the mandatory inverse-assignment comparison cannot be adjudicated. Step 2 must run '
                'and pass before this step.'.format(straight_dut_polarity, straight_peer_polarity))
            return

        # Relative to the straight-through record exactly ONE end inverts: complementary
        # roles (step 2) become identical roles (here), which is a single flip.
        dut_flipped = (dut_polarity == complement_of(straight_dut_polarity))
        peer_flipped = (peer_polarity == complement_of(straight_peer_polarity))
        if dut_flipped != peer_flipped:
            self.passed('Exactly one end inverted its role relative to step 2 (DUT {} -> {}, peer {} -> {}), '
                        'as a crossover cable requires'.format(
                            straight_dut_polarity, dut_polarity, straight_peer_polarity, peer_polarity))
        else:
            self.failed('Expected exactly one end to invert relative to step 2, but DUT {} -> {} and peer '
                        '{} -> {} ({} flipped)'.format(
                            straight_dut_polarity, dut_polarity, straight_peer_polarity, peer_polarity,
                            'both' if dut_flipped else 'neither'))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        # Mirror of configure(): re-assert default speed/duplex/polarity on both ends so
        # the next case does not inherit any state from this one.
        configureDefaultPort(self, dut, portA)
        configureDefaultPort(self, peer, portDut)


class TestCase_5(ATTestCase.TestCase):
    testCaseDesc = "With the CROSSOVER cable still in place, force the DUT copper test port to MDI: 'interface <port>' then 'polarity mdi'. Allow the link to settle, then read 'show running-config interface <port>', 'show interface <port>', 'show interface <port> status' and 'show interface <partner port>' on the partner."
    testCaseRef = 'AWPTCM-T33234, 9001.33234.5'
    testCaseMethod = "With the CROSSOVER cable still in place, force the DUT copper test port to MDI: 'interface <port>' then 'polarity mdi'. Allow the link to settle, then read 'show running-config interface <port>', 'show interface <port>', 'show interface <port> status' and 'show interface <partner port>' on the partner.\n"
    testCaseMethod += "Verify: Command accepted with no error; 'show running-config interface <port>' shows 'polarity mdi'; 'show interface <port>' reports current polarity mdi. The partner on automatic polarity adapts to the forced role: over a crossover cable it must resolve to the SAME role, so 'show interface <partner port>' reports current polarity mdi and 'show interface <port> status' reads 'connected'.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        # This step presumes the DUT test port starts from the documented defaults
        # (duplex auto, speed auto, polarity auto) so that forcing polarity mdi in
        # main() is the only change under test - establish that baseline ourselves,
        # and leave the partner on auto so its automatic crossover can complement.
        configureDefaultPort(self, dut, portA)
        configureDefaultPort(self, peer, portDut)
        time.sleep(3)

    def main(self):
        # legacy 5000_mdi_mdix/test-5000.0002-CopperFixed_Cross.py lines 209-271
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        self.log("STEP 6: With the CROSSOVER cable still in place, force the DUT copper test port to MDI: 'interface <port>' then 'polarity mdi'. Allow the link to settle, then read 'show running-config interface <port>', 'show interface <port>', 'show interface <port> status' and 'show interface <partner port>' on the partner.")

        dut.mode(')#')
        dut.cmd('interface {}'.format(portA.name))
        polarity_output = dut.cmd('polarity mdi')
        dut.mode('#')
        self.log('OBSERVED: polarity mdi command output on {}: {}'.format(portA.name, polarity_output))

        # Adjudicate acceptance on the platform's parser markers, not on a bare
        # 'error'/'invalid' substring scan of the command echo
        # (holistic review, TestCase_5).
        if cli_rejected(polarity_output):
            self.failed('polarity mdi command was rejected on {}: {}'.format(
                portA.name, polarity_output.strip()))
            return
        self.passed('polarity mdi command accepted on {} with no CLI parser error'.format(portA.name))

        # Let the forced role re-establish the link before reading the operational state.
        link_up = waitForLinkState(self, dut, portA, 'connected', 60)

        running_output = dut.cmd('show running-config interface {}'.format(portA.name))
        self.log('OBSERVED: show running-config interface {}: {}'.format(portA.name, running_output))

        if re.search(r'^\s*polarity\s+mdi\s*$', running_output, re.M):
            self.passed('show running-config interface {} shows polarity mdi'.format(portA.name))
        else:
            self.failed('show running-config interface {} does not show polarity mdi: {}'.format(
                portA.name, running_output))
            return

        dut.mode('#')
        interface_output = dut.cmd('show interface {}'.format(portA.name))
        self.log('OBSERVED: show interface {}: {}'.format(portA.name, interface_output))

        # Exact token: 'mdix' must not satisfy the forced-MDI assertion.
        resolved = current_polarity(interface_output)
        configured = configured_polarity(interface_output)

        if configured == 'mdi':
            self.passed('{} reports configured polarity mdi'.format(portA.name))
        else:
            self.failed('{} does not report configured polarity mdi (got {!r}): {}'.format(
                portA.name, configured, interface_output))
            return

        if resolved == 'mdi':
            self.passed('{} reports current polarity mdi (exact token)'.format(portA.name))
        else:
            self.failed('{} does not report current polarity mdi, current polarity is {!r}: {}'.format(
                portA.name, resolved, interface_output))
            return

        # The partner on automatic polarity ADAPTS to the forced role: over a crossover cable it
        # must resolve to the SAME role as the DUT's forced MDI.
        peer.mode('#')
        peer_output = peer.cmd('show interface {}'.format(portDut.name))
        self.log('OBSERVED: partner show interface {}: {}'.format(portDut.name, peer_output))
        peer_resolved = current_polarity(peer_output)
        if peer_resolved == 'mdi':
            self.passed('partner {} on automatic polarity resolved to mdi - the same role as the forced DUT, '
                        'the pairing over a crossover cable'.format(portDut.name))
        else:
            self.failed('partner {} reports current polarity {!r}; expected mdi (the same role as the DUT '
                        'forced to MDI over a crossover cable): {}'.format(portDut.name, peer_resolved, peer_output))
            return

        self.log('OBSERVED: link reached connected within the settle wait: {}'.format(link_up))
        status_output = dut.cmd('show interface {} status'.format(portA.name))
        self.log('OBSERVED: show interface {} status: {}'.format(portA.name, status_output))
        state, status_line = link_state_token(status_output, portA.name)
        if status_line is None:
            self.failed('port {} missing from show interface status output'.format(portA.name))
            return
        if state == 'connected':
            self.passed(
                '{} show interface status reads connected - the partner adapted to the forced MDI over the '
                'crossover cable: {}'.format(portA.name, status_line.strip()))
        else:
            self.failed(
                '{} link did not come up (status {!r}) although the partner resolved the pairing role: '
                '{}'.format(portA.name, state, status_line.strip()))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        # Mirror of configure()/main(): revert the DUT test port from the forced
        # polarity mdi back to the default auto/auto/auto configuration.
        configureDefaultPort(self, dut, portA)


class TestCase_6(ATTestCase.TestCase):
    testCaseDesc = "With the crossover cable still in place, force the DUT copper test port to MDI-X ('interface <port>' then 'polarity mdix'). Then force the PARTNER port to MDI ('interface <partner port>', 'polarity mdi') - the role that does NOT pair with MDI-X over a crossover cable - allow the link to settle and read 'show interface <port> status' on the DUT. Then force the partner port to MDI-X ('polarity mdix'), allow the link to settle, and read 'show running-config interface <port>', 'show interface <port>' and 'show interface <port> status' on the DUT. Finally return the partner port to 'polarity auto'."
    testCaseRef = 'AWPTCM-T33234, 9001.33234.6'
    testCaseMethod = "With the crossover cable still in place, force the DUT copper test port to MDI-X ('interface <port>' then 'polarity mdix'). Then force the PARTNER port to MDI ('interface <partner port>', 'polarity mdi') - the role that does NOT pair with MDI-X over a crossover cable - allow the link to settle and read 'show interface <port> status' on the DUT. Then force the partner port to MDI-X ('polarity mdix'), allow the link to settle, and read 'show running-config interface <port>', 'show interface <port>' and 'show interface <port> status' on the DUT. Finally return the partner port to 'polarity auto'.\n"
    testCaseMethod += "Verify: All commands accepted with no CLI error; DUT running-config shows 'polarity mdix'. With the partner forced to MDI the link is DOWN - 'show interface <port> status' does not read 'connected' - the mismatched MDI-X/MDI pairing over a crossover cable. With the partner forced to MDI-X the link returns to 'connected' and 'show interface <port>' reports current polarity mdix, proving the forced setting is the operational role.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        # Establish the baseline this step presumes: DUT test port back at defaults
        # (speed/duplex/polarity auto) before this step forces polarity mdix on it.
        configureDefaultPort(self, dut, portA)
        configureDefaultPort(self, peer, portDut)
        time.sleep(3)

    def main(self):
        # legacy 5000_mdi_mdix/test-5000.0002-CopperFixed_Cross.py lines 144-206
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        self.log("STEP 7: With the crossover cable still in place, force the DUT copper test port to MDI-X ('interface <port>' then 'polarity mdix'). Then force the PARTNER port to MDI ('interface <partner port>', 'polarity mdi') - the role that does NOT pair with MDI-X over a crossover cable - allow the link to settle and read 'show interface <port> status' on the DUT. Then force the partner port to MDI-X ('polarity mdix'), allow the link to settle, and read 'show running-config interface <port>', 'show interface <port>' and 'show interface <port> status' on the DUT. Finally return the partner port to 'polarity auto'.")

        dut.mode(')#')
        dut.cmd('interface {}'.format(portA.name))
        response = dut.cmd('polarity mdix')
        dut.mode('#')
        self.log('OBSERVED: polarity mdix response on {}: {}'.format(portA.name, response))
        if cli_rejected(response):
            self.failed("{} did not accept 'polarity mdix': {}".format(portA.name, response.strip()))
            return
        self.passed("{} accepted 'polarity mdix' with no CLI parser error".format(portA.name))

        running_output = dut.cmd('show running-config interface {}'.format(portA.name))
        self.log('OBSERVED: running-config: {}'.format(running_output))
        if re.search(r'^\s*polarity\s+mdix\s*$', running_output, re.M):
            self.passed("show running-config interface {} shows 'polarity mdix'".format(portA.name))
        else:
            self.failed("show running-config interface {} does not show 'polarity mdix': {}".format(
                portA.name, running_output))
            return
        if checkConfiguredPort(self, dut, portA, 'auto', 'auto', 'mdix'):
            self.passed('{} configured duplex/speed/polarity confirmed auto/auto/mdix'.format(portA.name))
        else:
            self.failed('{} configured duplex/speed/polarity did not match auto/auto/mdix'.format(portA.name))
            return

        # Phase 1 - NEGATIVE: force the PARTNER to MDI, the role that does NOT pair with MDI-X over a crossover cable. The link must go DOWN.
        if force_partner_polarity(self, peer, portDut, 'mdi') is None:
            return
        link_down = waitForLinkState(self, dut, portA, 'down', 45)
        status_output = dut.cmd('show interface {} status'.format(portA.name))
        self.log('OBSERVED (partner forced mdi): {}'.format(status_output))
        state, row = link_state_token(status_output, portA.name)
        if row is None:
            self.failed('port {} missing from show interface status output'.format(portA.name))
            return
        if link_down and state != 'connected':
            self.passed('{} link is DOWN ({!r}) with the DUT forced to mdix and the partner forced to mdi over '
                        'the crossover cable - the mismatched pairing: {}'.format(portA.name, state, row.strip()))
        else:
            self.failed('{} link still reads {!r} with the DUT forced to mdix and the partner forced to mdi '
                        'over the crossover cable; the mismatched pairing should not link: {}'.format(
                            portA.name, state, row.strip()))
            return

        # Phase 2 - POSITIVE: force the partner to MDI-X, the pairing role over a crossover cable. The link must
        # return and the DUT's operational role must be mdix.
        if force_partner_polarity(self, peer, portDut, 'mdix') is None:
            return
        link_up = waitForLinkState(self, dut, portA, 'connected', 60)
        status_output = dut.cmd('show interface {} status'.format(portA.name))
        interface_output = dut.cmd('show interface {}'.format(portA.name))
        self.log('OBSERVED (partner forced mdix): {}\n{}'.format(status_output, interface_output))
        state, row = link_state_token(status_output, portA.name)
        if row is None:
            self.failed('port {} missing from show interface status output'.format(portA.name))
            return
        if link_up and state == 'connected':
            self.passed('{} link returned to connected with the partner forced to mdix - the pairing role over '
                        'the crossover cable: {}'.format(portA.name, row.strip()))
        else:
            self.failed('{} did not return to connected ({!r}) with the partner forced to mdix over the crossover '
                        'cable: {}'.format(portA.name, state, row.strip()))
            return
        resolved = current_polarity(interface_output)
        if resolved == 'mdix':
            self.passed("show interface {} reports current polarity mdix: the forced setting is the "
                        "operational role".format(portA.name))
        elif resolved == 'mdi':
            self.failed("{} was forced to polarity mdix but show interface reports current polarity "
                        "{!r}: {}".format(portA.name, resolved, interface_output))
            return
        else:
            self.failed("{} link is up but show interface does not report a usable current polarity "
                        "(got {!r}): {}".format(portA.name, resolved, interface_output))
            return

        # Finally: the partner back to automatic polarity, as the action requires.
        force_partner_polarity(self, peer, portDut, 'auto')

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        # Mirror configure()/main(): both ends back to default auto/auto/auto, undoing the
        # forced DUT polarity and the two forced partner roles.
        configureDefaultPort(self, dut, portA)
        configureDefaultPort(self, peer, portDut)


class TestCase_7(ATTestCase.TestCase):
    testCaseDesc = "Prompt the operator to replace the crossover cable with the straight-through cable between the DUT test port and the partner port; then poll 'show interface <port> status' on the DUT for the link-state transition."
    testCaseRef = 'AWPTCM-T33234, 9001.33234.7'
    testCaseMethod = "Prompt the operator to replace the crossover cable with the straight-through cable between the DUT test port and the partner port; then poll 'show interface <port> status' on the DUT for the link-state transition.\n"
    testCaseMethod += "Verify: Operator confirms the cable swap; the DUT test port state change is observed in 'show interface <port> status'.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        # Precondition this step presumes: both ends of the link under test are left
        # at their default auto/auto/auto negotiation settings, so that the link's
        # response to a cable-type change is driven purely by Auto MDI/MDI-X
        # negotiation, not by a polarity/speed/duplex override left by an earlier case.
        configureDefaultPort(self, dut, portA)
        configureDefaultPort(self, peer, portDut)

    def main(self):
        # legacy 5703_Speed_Duplex_Polarity/test-5000.1003.py lines 32-55
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        self.log("STEP 8: Prompt the operator to replace the crossover cable with the straight-through cable between the DUT test port and the partner port; then poll 'show interface <port> status' on the DUT for the link-state transition.")

        dut.mode('#')
        before_output = dut.cmd('show interface {} status'.format(portA.name))
        before_state, before_row = link_state_token(before_output, portA.name)
        self.log('Link status before cable swap: {!r} ({})'.format(before_state, before_row))

        if before_state == 'connected':
            # Link UP before the swap: the state change to observe is the port LEAVING
            # connected when the crossover cable is pulled, then RETURNING once the
            # straight-through cable is fitted (two-phase shape, as TestCase_3).
            removed = yesNo(
                'Unplug the CROSSOVER cable between DUT port {} and partner port {} now. '
                'Confirm when the cable has been REMOVED'.format(portA.name, portDut.name))
            if not removed:
                self.failed('Operator did not confirm removal of the crossover cable between {} and '
                            '{}'.format(portA.name, portDut.name))
                return
            self.passed('Operator confirmed removal of the crossover cable between {} and {}'.format(
                portA.name, portDut.name))
            down_deadline = time.time() + 60
            down_state, down_row, down_seen = None, None, False
            while time.time() < down_deadline:
                output = dut.cmd('show interface {} status'.format(portA.name), log=False)
                down_state, down_row = link_state_token(output, portA.name)
                if down_row is not None and down_state != 'connected':
                    down_seen = True
                    break
                time.sleep(2)
            self.log('OBSERVED (down phase): row={}'.format(down_row))
            if down_seen:
                self.passed('DUT port {} left the connected state after the crossover cable was '
                            'removed: {}'.format(portA.name, down_row))
            else:
                self.failed('DUT port {} never left the connected state within 60 s of the operator '
                            'confirming cable removal: {}'.format(portA.name, down_row))
                return
            observed_from = down_state
            prompt = ('Now fit the STRAIGHT-THROUGH cable between DUT port {} and partner port {}. '
                      'Confirm when the cable is FITTED'.format(portA.name, portDut.name))
        else:
            # Link already DOWN before the swap (configure() returned both ends to auto, so a
            # down link here is unexpected but possible): the observable state change is
            # down -> connected once the straight-through cable is fitted.
            self.log('Link was {!r} before the swap: the state change to observe is a return to '
                     'connected'.format(before_state))
            observed_from = before_state
            prompt = ('Replace the crossover cable between DUT port {} and partner port {} '
                      'with a straight-through cable, then confirm'.format(portA.name, portDut.name))

        confirmed = yesNo(prompt)

        if not confirmed:
            self.failed('Operator did not confirm the crossover-to-straight-through cable '
                        'swap between {} and {}'.format(portA.name, portDut.name))
            return
        self.passed('Operator confirmed the crossover-to-straight-through cable swap '
                    'between {} and {}'.format(portA.name, portDut.name))

        # Poll for the link-state transition to connected after the swap.
        timeout_s = 120
        deadline = time.time() + timeout_s
        state = None
        row = None
        started = time.time()
        while time.time() < deadline:
            output = dut.cmd('show interface {} status'.format(portA.name), log=False)
            state, row = link_state_token(output, portA.name)
            if state == 'connected':
                break
            time.sleep(2)
        elapsed = time.time() - started
        self.log('OBSERVED: state={!r} row={}'.format(state, row))

        if row is None:
            self.failed('Port {} missing from show interface status output'.format(portA.name))
            return

        if state == 'connected':
            self.passed('DUT port {} state changed from {!r} to connected within {:.1f} s of the '
                        'straight-through cable swap: {}'.format(
                            portA.name, observed_from, elapsed, row.strip()))
        else:
            self.failed('DUT port {} did not show a connected state within {} s after '
                        'the straight-through cable swap: {}'.format(
                            portA.name, timeout_s, row.strip()))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        # Mirror configure(): leave both ends of the link at default auto/auto/auto
        # negotiation settings for the next case.
        configureDefaultPort(self, dut, portA)
        configureDefaultPort(self, peer, portDut)


class TestCase_8(ATTestCase.TestCase):
    testCaseDesc = "With the STRAIGHT-THROUGH cable in place, force the DUT copper test port to MDI-X ('interface <port>', 'polarity mdix'), allow the link to settle, then read 'show running-config interface <port>', 'show interface <port>', 'show interface <port> status' and 'show interface <partner port>' on the partner."
    testCaseRef = 'AWPTCM-T33234, 9001.33234.8'
    testCaseMethod = "With the STRAIGHT-THROUGH cable in place, force the DUT copper test port to MDI-X ('interface <port>', 'polarity mdix'), allow the link to settle, then read 'show running-config interface <port>', 'show interface <port>', 'show interface <port> status' and 'show interface <partner port>' on the partner.\n"
    testCaseMethod += "Verify: Running-config shows 'polarity mdix' and 'show interface <port>' reports current polarity mdix. The partner on automatic polarity adapts: over a straight-through cable it must resolve to the COMPLEMENTARY role, so 'show interface <partner port>' reports current polarity mdi and 'show interface <port> status' reads 'connected'.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        # This step presumes a straight-through cable is fitted between the DUT test
        # port and the PARTNER SWITCH port that main() measures (not the testbox NIC —
        # holistic review, TestCase_8), and that the port starts from the default
        # (auto/auto/auto) configuration so the polarity change made in main() is the
        # only variable under test.
        self.log('Confirming STRAIGHT-THROUGH cable is fitted between DUT port {} and partner '
                 'port {}'.format(portA.name, portDut.name))
        self.cable_confirmed = yesNo(
            'Is the STRAIGHT-THROUGH cable fitted between DUT port {} and partner port {}?'.format(
                portA.name, portDut.name))
        # Whatever the answer, leave the ports in the defined default state so the next
        # case never inherits an undefined configuration.
        configureDefaultPort(self, dut, portA)
        configureDefaultPort(self, peer, portDut)
        time.sleep(3)

    def main(self):
        # legacy 5000_mdi_mdix/test-5000.0001-CopperFixed_Straight.py lines 78-140
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        peer = self.testSet.peer
        portDut = peer.portDut
        self.log("STEP 9: With the STRAIGHT-THROUGH cable in place, force the DUT copper test port to MDI-X ('interface <port>', 'polarity mdix'), allow the link to settle, then read 'show running-config interface <port>', 'show interface <port>', 'show interface <port> status' and 'show interface <partner port>' on the partner.")

        if not getattr(self, 'cable_confirmed', False):
            self.failed('Operator did not confirm the STRAIGHT-THROUGH cable between DUT port {} and '
                        'partner port {}; the precondition this step requires is not in place'.format(
                            portA.name, portDut.name))
            return
        self.passed('Operator confirmed the STRAIGHT-THROUGH cable between DUT port {} and partner '
                    'port {}'.format(portA.name, portDut.name))

        dut.mode(')#')
        dut.cmd('interface {}'.format(portA.name))
        response = dut.cmd('polarity mdix')
        dut.mode('#')
        self.log('OBSERVED: polarity mdix response: {}'.format(response))
        if cli_rejected(response):
            self.failed('polarity mdix rejected by the CLI parser on {}: {}'.format(
                portA.name, response.strip()))
            return
        self.passed('polarity mdix accepted with no CLI parser error on {}'.format(portA.name))

        link_up = waitForLinkState(self, dut, portA, 'connected', 60)

        running_cfg = dut.cmd('show running-config interface {}'.format(portA.name))
        show_int = dut.cmd('show interface {}'.format(portA.name))
        show_status = dut.cmd('show interface {} status'.format(portA.name))
        output = '{}\n{}\n{}'.format(running_cfg, show_int, show_status)
        self.log('OBSERVED: {}'.format(output))

        if re.search(r'^\s*polarity\s+mdix\s*$', running_cfg, re.M):
            self.passed('running-config for {} shows polarity mdix'.format(portA.name))
        else:
            self.failed('running-config for {} does not show polarity mdix: {}'.format(
                portA.name, running_cfg))
            return

        configured = configured_polarity(show_int)
        if configured == 'mdix':
            self.passed('{} show interface reports configured polarity mdix'.format(portA.name))
        else:
            self.failed('{} show interface does not report configured polarity mdix (got {!r}): {}'.format(
                portA.name, configured, show_int))
            return

        # The verify demands the OPERATIONAL role too, not just the configured value
        # (holistic review, TestCase_8).
        resolved = current_polarity(show_int)
        if resolved == 'mdix':
            self.passed('{} show interface reports current polarity mdix, the forced role is the '
                        'operational role'.format(portA.name))
        else:
            self.failed('{} show interface does not report current polarity mdix (got {!r}): {}'.format(
                portA.name, resolved, show_int))
            return

        # The partner on automatic polarity ADAPTS to the forced role: over a straight-through
        # cable it must resolve to the COMPLEMENTARY role (mdi) of the DUT's forced MDI-X.
        peer = self.testSet.peer
        portDut = peer.portDut
        peer.mode('#')
        peer_output = peer.cmd('show interface {}'.format(portDut.name))
        self.log('OBSERVED: partner show interface {}: {}'.format(portDut.name, peer_output))
        peer_resolved = current_polarity(peer_output)
        if peer_resolved == 'mdi':
            self.passed('partner {} on automatic polarity resolved to mdi - the complement of the forced DUT '
                        'MDI-X, the pairing over a straight-through cable'.format(portDut.name))
        else:
            self.failed('partner {} reports current polarity {!r}; expected mdi (the complement of the DUT '
                        'forced to MDI-X over a straight-through cable): {}'.format(
                            portDut.name, peer_resolved, peer_output))
            return

        self.log('OBSERVED: link reached connected within the 60 s settle wait: {}'.format(link_up))
        state, status_line = link_state_token(show_status, portA.name)
        if status_line is None:
            self.failed('port {} missing from show interface status output'.format(portA.name))
            return
        elif state == 'connected':
            self.passed(
                '{} show interface status reads connected: forced MDI-X against a '
                'straight-through cable and auto-polarity partner is the matched pair'.format(
                    portA.name))
        else:
            self.failed('{} show interface status reads {!r} ({}), expected connected'.format(
                portA.name, state, status_line.strip()))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        portA = dut.portA
        # Mirror configure(): return the port to the default auto/auto/auto state,
        # undoing the forced polarity mdix applied in main().
        configureDefaultPort(self, dut, portA)


